-- ==========================================================================
-- V1 — Esquema inicial de la barbería
-- ==========================================================================
--
-- Este archivo define TODAS las tablas. Es la única fuente del esquema:
-- Hibernate nunca lo modifica (spring.jpa.hibernate.ddl-auto = none).
--
-- El SQL es estándar y portable: funciona igual en H2 (desarrollo y
-- pruebas) y en PostgreSQL (producción). Por eso se evita todo lo que
--depende de un motor en particular, como los índices parciales de PostgreSQL.
--
-- Sobre "GENERATED BY DEFAULT AS IDENTITY": es la forma estándar de SQL
-- para columnas autoincremental. La entiende PostgreSQL desde la versión
-- 10 y H2 también, así que no hace falta identity/serial distintos por motor.
-- ==========================================================================


-- --------------------------------------------------------------------------
-- barber — Barberos
-- --------------------------------------------------------------------------
-- Hoy hay un solo barbero, pero la tabla existe igual: la agenda, los
-- turnos y la garantía de no superposición funcionan por barbero, así que
-- agregar un segundo después no obliga a migrar datos ya guardados.
-- --------------------------------------------------------------------------
CREATE TABLE barber (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    active      BOOLEAN      NOT NULL DEFAULT TRUE,
    sort_order  INTEGER      NOT NULL DEFAULT 0
);


-- --------------------------------------------------------------------------
-- service — Catálogo de servicios
-- --------------------------------------------------------------------------
CREATE TABLE service (
    id                BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name              VARCHAR(80)   NOT NULL,
    description       VARCHAR(500),
    price             NUMERIC(10, 2) NOT NULL,
    duration_minutes  INTEGER       NOT NULL,
    active            BOOLEAN       NOT NULL DEFAULT TRUE,
    sort_order        INTEGER       NOT NULL DEFAULT 0,

    CONSTRAINT uq_service_name   UNIQUE (name),
    CONSTRAINT ck_service_price  CHECK (price >= 0),
    CONSTRAINT ck_service_dur    CHECK (duration_minutes > 0)
);

-- El catálogo se ordena por sort_order y se filtra por active.
CREATE INDEX idx_service_active ON service (active, sort_order);


-- --------------------------------------------------------------------------
-- business_hours — Horario de atención semanal
-- --------------------------------------------------------------------------
-- Siempre hay 7 filas, una por día, incluso los que están cerrados:
-- así el dueño ve el horario completo en el panel y puede modificarlo.
-- --------------------------------------------------------------------------
CREATE TABLE business_hours (
    id          BIGINT  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    day_of_week INTEGER NOT NULL,
    open_time   TIME,
    close_time  TIME,
    is_closed   BOOLEAN NOT NULL DEFAULT FALSE,

    CONSTRAINT uq_bh_day UNIQUE (day_of_week),
    -- 1 = lunes … 7 = domingo
    CONSTRAINT ck_bh_day CHECK (day_of_week BETWEEN 1 AND 7),
    -- Si no está cerrado, tiene que tener horario completo.
    CONSTRAINT ck_bh_times CHECK (
        is_closed = TRUE
        OR (open_time IS NOT NULL AND close_time IS NOT NULL AND close_time > open_time)
    )
);


-- --------------------------------------------------------------------------
-- customer — Clientes
-- --------------------------------------------------------------------------
-- Se guarda lo mínimo indispensable: nombre y teléfono.
-- El teléfono se guarda SOLO con dígitos, para poder compararlo sin
-- depender de cómo lo escribió el cliente.
-- --------------------------------------------------------------------------
CREATE TABLE customer (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    phone       VARCHAR(32)  NOT NULL,
    created_at  TIMESTAMP    NOT NULL
);

CREATE INDEX idx_customer_phone ON customer (phone);


-- --------------------------------------------------------------------------
-- appointment — Turnos
-- --------------------------------------------------------------------------
-- "reference" es el código corto y público que recibe el cliente
-- (por ejemplo BT-7K2M9Q). No es secuencial a propósito: si lo fuera,
-- cualquiera podría probarlos y ver los turnos ajenos.
--
-- Los horarios se guardan como la hora LOCAL de la barbería (no en UTC).
-- Para una sede única con una sola zona horaria, guardar el momento local
-- simplifica el cálculo de "el bloque de las 10:00" y evita que H2 y
-- PostgreSQL se comporten distinto.
-- --------------------------------------------------------------------------
CREATE TABLE appointment (
    id                   BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reference            VARCHAR(16)  NOT NULL,
    customer_id          BIGINT       NOT NULL,
    barber_id            BIGINT       NOT NULL,
    service_id           BIGINT       NOT NULL,
    starts_at            TIMESTAMP    NOT NULL,
    ends_at              TIMESTAMP    NOT NULL,
    status               VARCHAR(20)  NOT NULL,
    notes                VARCHAR(500),
    cancellation_reason  VARCHAR(200),
    created_at           TIMESTAMP    NOT NULL,
    updated_at           TIMESTAMP    NOT NULL,

    CONSTRAINT uq_appointment_ref     UNIQUE (reference),
    CONSTRAINT fk_appt_customer       FOREIGN KEY (customer_id) REFERENCES customer (id),
    CONSTRAINT fk_appt_barber         FOREIGN KEY (barber_id)   REFERENCES barber (id),
    CONSTRAINT fk_appt_service        FOREIGN KEY (service_id)  REFERENCES service (id),
    CONSTRAINT ck_appt_status CHECK (
        status IN ('PENDING', 'CONFIRMED', 'COMPLETED', 'CANCELLED')
    ),
    CONSTRAINT ck_appt_range CHECK (ends_at > starts_at)
);

CREATE INDEX idx_appointment_starts   ON appointment (starts_at);
CREATE INDEX idx_appointment_barber   ON appointment (barber_id, starts_at);
CREATE INDEX idx_appointment_status   ON appointment (status);


-- --------------------------------------------------------------------------
-- appointment_slot — Bloqueo de la agenda
-- --------------------------------------------------------------------------
-- ESTA ES LA TABLA QUE GARANTIZA QUE NO SE SUPERPUONGAN LAS RESERVAS.
--
-- La idea: la jornada se divide en bloques de 30 minutos (AppConfig). Cada
-- reserva ocupa VARIOS bloques, y se inserta una fila por cada bloque.
-- Un corte de 60 minutos a las 10:00 inserta (barber, 10:00) y (barber, 10:30).
--
-- Si alguien intenta tomar un bloque ya ocupado, el INSERT viola la clave
-- primaria compuesta y la BASE DE DATOS rechaza la operación. La aplicación
-- solo tiene que traducir ese error a un 409.
--
-- ¿Por qué no alcanza con UNIQUE(barber_id, starts_at) en appointment?
-- Porque dos turnos pueden empezar en instantes distintos y pisarse:
--   10:00 → 11:00   y   10:30 → 11:30
-- Esos dos starts_at son distintos, así que el UNIQUE no se activaría y los
-- dos clientes terminarían en la misma silla al mismo tiempo.
--
-- ¿Por qué no un índice parcial de PostgreSQL (WHERE status = 'PENDING')?
-- Porque H2 no los soporta. Con esta tabla la lógica es idéntica en los
-- dos motores y el desarrollo local se parece a la producción.
-- --------------------------------------------------------------------------
CREATE TABLE appointment_slot (
    barber_id       BIGINT    NOT NULL,
    slot_start      TIMESTAMP NOT NULL,
    appointment_id  BIGINT    NOT NULL,

    CONSTRAINT pk_appointment_slot PRIMARY KEY (barber_id, slot_start),
    CONSTRAINT fk_slot_barber FOREIGN KEY (barber_id) REFERENCES barber (id),
    CONSTRAINT fk_slot_appointment FOREIGN KEY (appointment_id) REFERENCES appointment (id)
);

-- Al cancelar un turno se borran sus filas por este índice.
CREATE INDEX idx_slot_appointment ON appointment_slot (appointment_id);


-- --------------------------------------------------------------------------
-- time_off — Bloqueos de agenda
-- --------------------------------------------------------------------------
-- Vacaciones, feriados, un almuerzo largo, un curso.
-- barber_id NULL significa que el bloqueo afecta a todo el local.
-- --------------------------------------------------------------------------
CREATE TABLE time_off (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    barber_id   BIGINT,
    starts_at   TIMESTAMP    NOT NULL,
    ends_at     TIMESTAMP    NOT NULL,
    reason      VARCHAR(200),

    CONSTRAINT fk_timeoff_barber FOREIGN KEY (barber_id) REFERENCES barber (id),
    CONSTRAINT ck_timeoff_range  CHECK (ends_at > starts_at)
);

CREATE INDEX idx_time_off_range ON time_off (starts_at, ends_at);
